#: Student-facing notes for the Economics shelf.  These are presentation
#: metadata, not arithmetic: the numbers still come from the frozen methods.
#: A tool is shown only with its level, formula, steps, common mistakes and a
#: diagram key (or an explicit reason there is no diagram).
#: One-line "what to gather" for a tool tile.  Student-facing, not a method description.
