#: Terms a student meets on the Economics page, in plain language.
ECONOMICS_GLOSSARY = [
    {"term": "P*", "definition": "The equilibrium price, where quantity demanded equals quantity supplied."},
    {"term": "Q*", "definition": "The equilibrium quantity traded at P*."},
    {"term": "CS", "definition": "Consumer surplus: the area below the demand curve and above the price."},
    {"term": "PS", "definition": "Producer surplus: the area above the supply curve and below the price."},
    {"term": "DWL", "definition": "Deadweight loss: the surplus lost when the quantity traded is not the efficient quantity."},
    {"term": "E", "definition": "Price elasticity of demand: the percentage change in quantity divided by the percentage change in price."},
    {"term": "Pc / Ps", "definition": "The consumer price and the producer price when a tax drives a wedge between them."},
    {"term": "HHI", "definition": "Herfindahl-Hirschman index: the sum of squared percentage market shares, from 0 to 10,000."},
    {"term": "CR4", "definition": "The combined market share of the four largest firms."},
    {"term": "GDP", "definition": "Gross domestic product: the market value of final goods and services produced inside a country in a period."},
    {"term": "GNP / NNP", "definition": "Gross national product adds net factor income from abroad; net national product subtracts depreciation."},
    {"term": "CPI", "definition": "Consumer price index: the cost of a fixed basket relative to a base period, usually scaled to 100."},
    {"term": "CAGR", "definition": "Compound annual growth rate: the constant yearly rate that turns the start value into the end value."},
    {"term": "LFPR", "definition": "Labour-force participation rate: the labour force divided by the working-age population."},
    {"term": "MPC", "definition": "Marginal propensity to consume: the fraction of an extra unit of income spent on consumption."},
    {"term": "Debt-to-GDP", "definition": "The debt stock divided by nominal GDP; the standard scale for comparing debt across economies."},
    {"term": "Pigouvian tax", "definition": "A tax equal to the marginal external cost at the social optimum."},
    {"term": "Gini coefficient", "definition": "An inequality index between zero (perfect equality) and one (one person has all income)."},
    {"term": "HDI", "definition": "Human Development Index: the geometric mean of life, education and income indices."},
    {"term": "PPP", "definition": "Purchasing-power parity: the exchange rate that equalises the cost of a basket across countries."},
    {"term": "IRP", "definition": "Interest-rate parity: the forward rate implied by the two countries' interest rates."},
    {"term": "BoP", "definition": "Balance of payments: the current, capital and financial accounts, which add to zero."},
    {"term": "DiD", "definition": "Difference-in-differences: the treated change minus the control change."},
    {"term": "Nash equilibrium", "definition": "A cell where neither player can gain by switching strategy alone."},
    {"term": "Cournot", "definition": "Quantity competition in which each firm best-responds to the other's output."},
]


