#: Terms a student meets on the Finance page, in plain language.
FINANCE_GLOSSARY = [
    {"term": "NPV", "definition": "Net present value: the value today of a project's future cash flows, less the outlay, at a declared discount rate."},
    {"term": "IRR", "definition": "Internal rate of return: the discount rate at which NPV is zero."},
    {"term": "WACC", "definition": "Weighted average cost of capital: the blended after-tax cost of equity and debt, weighted by market values."},
    {"term": "CAPM", "definition": "Capital asset pricing model: cost of equity = risk-free rate + beta x market risk premium."},
    {"term": "Beta", "definition": "The sensitivity of an asset's return to the market's return; the market itself has a beta of one."},
    {"term": "YTM", "definition": "Yield to maturity: the single discount rate that makes a bond's coupon and face payments equal its price."},
    {"term": "Duration", "definition": "The present-value-weighted average time to a bond's cash flows; modified duration measures price sensitivity to yield."},
    {"term": "Convexity", "definition": "The curvature of the price-yield relation; it improves the duration estimate for larger yield changes."},
    {"term": "EOQ", "definition": "Economic order quantity: the order size that minimises the sum of ordering and holding costs."},
    {"term": "CCC", "definition": "Cash conversion cycle: receivable days plus inventory days minus payable days."},
    {"term": "VaR", "definition": "Value at risk: the loss that is not expected to be exceeded at a declared confidence over a declared horizon."},
    {"term": "CVaR", "definition": "Conditional value at risk (expected shortfall): the average loss in the tail beyond VaR."},
    {"term": "Delta", "definition": "The change in an option's price for a one-unit change in the underlying; a hedge ratio, not a probability."},
    {"term": "Hedge", "definition": "A position that offsets a risk; here, a forward rate that fixes the domestic value of a foreign-currency exposure."},
    {"term": "Enterprise value", "definition": "The value of the operating business: equity value plus net debt and other claims."},
    {"term": "Net debt", "definition": "Interest-bearing debt minus cash and cash equivalents."},
    {"term": "EBIT / EBITDA", "definition": "Earnings before interest and tax; EBITDA also excludes depreciation and amortisation."},
    {"term": "EPS", "definition": "Earnings per share: profit available to ordinary shareholders divided by the number of shares."},
    {"term": "ROE", "definition": "Return on equity: net income divided by equity; DuPont splits it into margin, turnover and leverage."},
    {"term": "Common-size", "definition": "A line item expressed as a percentage of a base such as revenue, so statements of different size can be compared."},
    {"term": "CAGR", "definition": "Compound annual growth rate: the constant yearly rate that turns the first period's value into the last."},
    {"term": "Altman Z", "definition": "A five-term score built from working capital, retained earnings, EBIT, market equity and sales, scaled by assets and liabilities."},
]

GLOSSARIES = {"economics": ECONOMICS_GLOSSARY, "finance": FINANCE_GLOSSARY}

#: Terms a student meets on the Entrepreneurship page, in plain language.
ENTREPRENEURSHIP_GLOSSARY = [
    {"term": "TAM", "definition": "Total addressable market: all the spending in the market you have described, before your own reach."},
    {"term": "SAM", "definition": "Serviceable available market: the part of TAM you can realistically reach with your location, channel and capacity."},
    {"term": "SOM", "definition": "Serviceable obtainable market: the part of SAM you can actually win, given competitors and your plan."},
    {"term": "Contribution margin", "definition": "Price minus variable cost per unit: what each sale leaves towards fixed costs and profit."},
    {"term": "CM ratio", "definition": "The contribution margin divided by the price; the share of each dollar of sales that covers fixed costs."},
    {"term": "Break-even point", "definition": "The sales volume or revenue at which total contribution equals fixed cost, so profit is zero."},
    {"term": "Margin of safety", "definition": "Expected sales minus break-even sales: how far sales can fall before the business makes a loss."},
    {"term": "Target profit", "definition": "A declared pre-tax profit goal; the volume needed is (fixed cost + target) / contribution margin."},
    {"term": "Markup", "definition": "A percentage added to cost to set a price. A markup on cost is not the same as a margin on price."},
    {"term": "CAC", "definition": "Customer acquisition cost: what you spend, on average, to win one customer."},
    {"term": "LTV", "definition": "Customer lifetime value: the contribution a customer brings over their life; here, margin divided by the declared churn rate."},
    {"term": "Churn", "definition": "The share of customers who stop buying each period, entered as a decimal (5% is 0.05)."},
    {"term": "Burn rate", "definition": "The net cash a business spends each month when costs exceed receipts."},
    {"term": "Runway", "definition": "How many months the opening cash lasts at the declared burn rate, before the balance reaches zero."},
    {"term": "Working capital", "definition": "The cash tied up in day-to-day operations: stock, receivables and the bills you must pay."},
    {"term": "Contingency", "definition": "A declared reserve on top of the estimated requirement, for costs that turn out higher than planned."},
    {"term": "ROI", "definition": "Return on investment: the net gain divided by the total amount invested."},
    {"term": "Feasibility study", "definition": "The assignment document that tests a business idea across market, operations and finance before launch."},
    {"term": "Pro-forma", "definition": "A projected financial statement built from declared assumptions rather than past results."},
    {"term": "SROI", "definition": "Social return on investment: the present value of social benefits relative to the investment, under declared attribution assumptions."},
    {"term": "Conversion rate", "definition": "The share of the people at one funnel stage who reach the next stage."},
    {"term": "Funnel", "definition": "The ordered stages a customer passes through, from first contact to purchase, with the count at each stage."},
    {"term": "Cohort", "definition": "A group of customers who started in the same period, followed together over later periods."},
    {"term": "Retention", "definition": "The share of a cohort still buying in a later period; its complement is churn."},
    {"term": "Pre-money", "definition": "The agreed value of the company before a new investment."},
    {"term": "Post-money", "definition": "The pre-money value plus the new investment."},
    {"term": "Cap table", "definition": "The list of who owns which shares and what percentage each holder has, fully diluted."},
    {"term": "Dilution", "definition": "The fall in an existing holder's percentage when new shares are issued."},
    {"term": "Option pool", "definition": "Shares reserved for future employees, usually expressed as a share of the fully diluted company."},
    {"term": "Purchase intent", "definition": "What survey respondents say they would do, weighted into an expected buying rate."},
    {"term": "Projection", "definition": "A period-by-period table built from declared assumptions, not a fitted forecast."},
    {"term": "Segmentation", "definition": "Dividing a market into groups with different needs or behaviour."},
    {"term": "Targeting", "definition": "Choosing which segments to serve, and saying why."},
    {"term": "Positioning", "definition": "The place you want your offer to occupy in the target customer's mind."},
]

GLOSSARIES["entrepreneurship"] = ENTREPRENEURSHIP_GLOSSARY

#: Terms a student meets on the Marketing & customers page, in plain language.
MARKETING_GLOSSARY = [
    {"term": "Market sizing (TAM/SAM/SOM)", "definition": "Total addressable market is all the spending in the market you describe; the serviceable available market is the part you can reach; the serviceable obtainable market is the part you can realistically win."},
    {"term": "Demand curve", "definition": "How quantity demanded changes as price changes; its slope and the elasticity at the mean are what the demand tool reports."},
    {"term": "Price elasticity", "definition": "The percentage change in quantity demanded for a one-percent change in price; above one in absolute value is elastic, below one is inelastic."},
    {"term": "Purchase intent", "definition": "What survey respondents say they will buy, weighted into an expected buying rate; a statement of intent, not a record of purchases."},
    {"term": "CAC", "definition": "Customer acquisition cost: what you spend, on average, to win one customer."},
    {"term": "LTV", "definition": "Customer lifetime value: the contribution a customer brings over their life; here, margin divided by the declared churn rate."},
    {"term": "Churn", "definition": "The share of customers who stop buying each period, entered as a decimal (5% is 0.05)."},
    {"term": "Retention", "definition": "The share of a cohort still buying in a later period; its complement is churn."},
    {"term": "Cohort", "definition": "A group of customers who started in the same period, followed together over later periods."},
    {"term": "Contribution margin", "definition": "Price minus variable cost per unit: what each sale leaves towards fixed costs and profit."},
    {"term": "Funnel", "definition": "The ordered stages a customer passes through, from first contact to purchase, with the count at each stage."},
    {"term": "Conversion rate", "definition": "The share of the people at one stage who reach the next stage, or the share of visitors who complete the desired action."},
    {"term": "Trial-to-paid rate", "definition": "The share of free trials that become paying customers, measured over a declared window."},
    {"term": "CTR", "definition": "Click-through rate: clicks divided by impressions."},
    {"term": "CPC", "definition": "Cost per click: advertising spend divided by clicks."},
    {"term": "CPM", "definition": "Cost per thousand impressions: spend divided by impressions, multiplied by 1,000."},
    {"term": "CPA", "definition": "Cost per acquisition: spend divided by the number of customers or actions won."},
    {"term": "ROAS", "definition": "Return on ad spend: revenue attributed to the campaign divided by the spend."},
    {"term": "ACoS", "definition": "Advertising cost of sales: spend divided by revenue, the inverse of ROAS, expressed as a percentage."},
    {"term": "Break-even ROAS", "definition": "The ROAS at which campaign revenue exactly covers spend after the contribution margin: 1 / contribution margin ratio."},
    {"term": "Attribution", "definition": "The rule that decides which touchpoint receives credit for a conversion; first-click, last-click, linear and position-based rules give different answers."},
    {"term": "Incrementality", "definition": "The conversions that would not have happened without the campaign; a causal question that attribution credit alone cannot answer."},
    {"term": "UTM", "definition": "The tagging convention (source, medium, campaign, content, term) that lets analytics group visits by where they came from."},
    {"term": "SEO", "definition": "Search engine optimisation: earning unpaid search traffic by making pages relevant and technically sound."},
    {"term": "SEM", "definition": "Search engine marketing: paid search advertising, usually charged per click."},
    {"term": "CRO", "definition": "Conversion-rate optimisation: changing a page or journey and testing whether the completion rate really improved."},
    {"term": "A/B test", "definition": "A controlled comparison of two versions, where the difference in outcomes is tested against the range chance alone could produce."},
    {"term": "Statistical power", "definition": "The chance a test detects a real effect of a declared size; it sets the sample you need before you start."},
    {"term": "MQL / SQL", "definition": "Marketing-qualified lead and sales-qualified lead: two declared stages a lead passes before it becomes an opportunity."},
    {"term": "Media mix", "definition": "How the budget is divided across channels, and the evidence for what each channel returns."},
    {"term": "RFM", "definition": "Recency, frequency and monetary value: three transaction-based measures used to group customers by buying behaviour."},
    {"term": "Kano model", "definition": "Classifies product attributes by how their presence or absence affects satisfaction, from must-be to attractive."},
    {"term": "SERVQUAL", "definition": "A service-quality instrument that compares customer expectations with perceptions across declared dimensions."},
    {"term": "Quintile score", "definition": "A one-to-five band given by ranking the customers in your own file into five equal-count groups; the top band is five, and recency is ranked in reverse."},
    {"term": "RFM segment", "definition": "A label taken from a declared grid of recency, frequency and monetary scores, such as Champions or At risk; the label describes buying behaviour in one snapshot."},
    {"term": "Reach", "definition": "The number of people who see a vehicle at least once in the period, counted once each however many times they see it."},
    {"term": "Reach share", "definition": "Reach divided by the declared target population, expressed as a decimal (45% is 0.45)."},
    {"term": "Average frequency", "definition": "The average number of times a reached person sees the message; for a plan it is gross impressions divided by combined reach."},
    {"term": "Gross impressions", "definition": "Reach multiplied by average frequency: a count of exposures, not of people."},
    {"term": "GRP", "definition": "Gross rating points: reach share times average frequency times one hundred. Points add up across vehicles; people do not."},
    {"term": "CPP", "definition": "Cost per rating point: cost divided by gross rating points, the price of one percent of the population seeing one insertion."},
    {"term": "Net reach", "definition": "The combined number of different people a set of vehicles reaches; estimated here by the random-duplication formula, so it is an upper bound."},
    {"term": "Market share", "definition": "The firm's sales divided by the total sales of the declared market, over the same period and in the same currency."},
    {"term": "Penetration", "definition": "The share of the declared target population that buys; it counts buyers once, however often they buy."},
    {"term": "Relative market share", "definition": "The firm's sales divided by the largest declared competitor's sales; above one means the firm is the leader."},
    {"term": "Customer lifetime value (CLV)", "definition": "The margin a customer is expected to leave over a declared horizon, discounted to today and reduced each period by churn."},
    {"term": "Discount rate", "definition": "The per-period rate used to bring a future amount back to today; a higher rate makes future margin worth less."},
    {"term": "Profit concentration", "definition": "How few segments produce a declared share of the total profit, read from the segments ranked by profit."},
]

GLOSSARIES["marketing"] = MARKETING_GLOSSARY

#: Terms a student meets on the Accounting page.
ACCOUNTING_GLOSSARY = [
    {"term": "Debit / credit", "definition": "The two sides of every entry; total debits must equal total credits before anything is posted."},
    {"term": "Journal", "definition": "The dated list of balanced entries that the ledger and the statements are built from."},
    {"term": "Ledger", "definition": "The accounts and their postings, rebuilt from the journal."},
    {"term": "Trial balance", "definition": "Every account's closing balance on its natural side, with debits and credits in total agreement."},
    {"term": "Accrual", "definition": "A cost or revenue recognised in the period it belongs to, before cash moves."},
    {"term": "Prepayment", "definition": "A payment made before the period it covers, held as an asset until it expires."},
    {"term": "Depreciation", "definition": "The systematic allocation of an asset's cost over its useful life; it is not a cash payment."},
    {"term": "Accumulated depreciation", "definition": "The total depreciation charged against an asset since it was bought; a contra asset."},
    {"term": "Closing entries", "definition": "The period-end entries that clear income and expense accounts into retained earnings."},
    {"term": "Retained earnings", "definition": "Cumulative profit kept in the business after dividends, rolled forward each period."},
    {"term": "Gross profit", "definition": "Revenue less cost of sales, before operating expenses."},
    {"term": "Working capital", "definition": "Current assets less current liabilities: what is tied up in day-to-day operations."},
    {"term": "Current ratio", "definition": "Current assets divided by current liabilities; a liquidity measure, not a verdict."},
    {"term": "Variance", "definition": "Actual cost less the standard cost of the output achieved; positive is unfavourable."},
    {"term": "Favourable / unfavourable", "definition": "Whether actual cost came in below or above the declared standard."},
    {"term": "Standard cost", "definition": "The declared quantity and price (or hours and rate) allowed per unit of output."},
    {"term": "Taxable income", "definition": "The income the tax rate is applied to, after the adjustments the jurisdiction requires; here it is the figure you declare."},
    {"term": "VAT", "definition": "Value-added tax: output tax on sales less input tax on purchases, remitted by the registered business."},
    {"term": "Deferred tax", "definition": "Tax attributed to a temporary difference between accounting and taxable amounts, at the declared rate."},
]

#: Terms a student meets on the Operations and Supply chain pages.
OPERATIONS_GLOSSARY = [
    {"term": "Throughput", "definition": "The rate at which the process produces finished units; it is set by the bottleneck."},
    {"term": "Capacity", "definition": "The most a resource can produce in a period at its declared rate."},
    {"term": "Bottleneck", "definition": "The resource with the smallest capacity; extra capacity elsewhere does not raise output."},
    {"term": "Utilisation", "definition": "Demand or load divided by capacity."},
    {"term": "Cycle time", "definition": "The time between one unit leaving the process and the next."},
    {"term": "Takt time", "definition": "Available time divided by customer demand: the pace the process must keep."},
    {"term": "Work in progress", "definition": "Units started but not finished; it ties up cash and lengthens the lead time."},
    {"term": "Lead time", "definition": "The elapsed time from an order being placed to the goods arriving."},
    {"term": "EOQ", "definition": "Economic order quantity: the order size that minimises ordering plus holding cost."},
    {"term": "Safety stock", "definition": "Buffer inventory held against demand or lead-time variability."},
    {"term": "Reorder point", "definition": "The inventory level at which a new order is placed: lead-time demand plus safety stock."},
    {"term": "Service level", "definition": "The probability of not running out during a replenishment cycle, declared by you."},
    {"term": "Arrival rate", "definition": "The average number of customers or jobs arriving per period."},
    {"term": "Service rate", "definition": "The average number a single server can complete per period."},
    {"term": "Queue length", "definition": "Customers waiting, excluding the one being served."},
    {"term": "Little's law", "definition": "Average customers in a system equal the arrival rate times the average time in it."},
    {"term": "M/M/1", "definition": "One server, random arrivals and random service times with constant averages."},
    {"term": "Changeover", "definition": "The time to switch a resource from one product to another; it is not in a steady-state capacity figure."},
    {"term": "Line balancing", "definition": "Assigning tasks to workstations so each station fits inside the cycle time while respecting precedence."},
    {"term": "Ranked positional weight", "definition": "A task's own time plus the time of every task that must follow it; used to rank tasks when balancing."},
]

GLOSSARIES["accounting"] = ACCOUNTING_GLOSSARY
GLOSSARIES["operations"] = OPERATIONS_GLOSSARY
GLOSSARIES["supply-chain"] = OPERATIONS_GLOSSARY

#: Terms a student meets on the Project management page.  Where a term names a
#: method the product does not run yet, the definition says so rather than
#: implying a calculation that is not there.
PROJECT_MANAGEMENT_GLOSSARY = [
    {"term": "Business case", "definition": "The argument for committing money to a project: the need, the options considered, the expected costs and benefits, and the reason to proceed."},
    {"term": "Project charter", "definition": "The short authorisation that names the objective, scope, sponsor, budget and success measures before work starts."},
    {"term": "Scope", "definition": "What the project will and will not deliver. Scope that is not written down cannot be controlled."},
    {"term": "Deliverable", "definition": "A verifiable output the project hands over, such as a report, a system or a completed building."},
    {"term": "Work breakdown structure (WBS)", "definition": "The project scope broken into deliverables and work packages small enough to estimate and assign."},
    {"term": "Work package", "definition": "The smallest unit of the WBS: one piece of work with an owner, a cost and a completion test."},
    {"term": "Milestone", "definition": "A checkpoint with no duration, used to mark a decision, a handover or the end of a stage."},
    {"term": "Dependency", "definition": "A task that must finish (or start) before another can proceed."},
    {"term": "Critical path", "definition": "The longest chain of dependent tasks; it sets the shortest possible project duration and has no float. The shelf computes it from the activity list and durations you declare."},
    {"term": "Gantt chart", "definition": "A bar chart of tasks against calendar time, showing duration, sequence and overlap. The product does not draw one yet."},
    {"term": "RACI", "definition": "A responsibility matrix: Responsible does the work, Accountable owns the outcome, Consulted gives input, Informed is kept up to date."},
    {"term": "Stakeholder", "definition": "Anyone who affects or is affected by the project, including the sponsor, users, suppliers and the community."},
    {"term": "Risk register", "definition": "The list of identified risks with likelihood, impact, response, owner and review date."},
    {"term": "Contingency", "definition": "A declared reserve of money or time held for risks that are known to be possible but not yet priced exactly."},
    {"term": "Baseline", "definition": "The approved scope, cost and schedule against which later change and performance are measured."},
    {"term": "Earned value (PV, EV, AC)", "definition": "Planned value, earned value and actual cost: the budgeted worth of work planned, the budgeted worth of work done, and what it actually cost. Supply the three cumulative figures at one status date."},
    {"term": "CPI / SPI", "definition": "Cost performance index (EV / AC) and schedule performance index (EV / PV); above one is ahead of the baseline, below one is behind. The shelf computes both, plus the estimate and variance at completion."},
    {"term": "Benefits realisation", "definition": "Checking after delivery whether the benefits in the business case actually appeared, and who owns that check."},
    {"term": "Lessons learned", "definition": "The close-out review of what worked, what did not, and what the next project should change."},
    {"term": "PRINCE2", "definition": "A stage-gated project method organised around roles, business justification, controls and tailoring to the project."},
    {"term": "PMBOK / PMI", "definition": "The Project Management Institute's body of knowledge: knowledge areas and performance domains that change between editions."},
    {"term": "Scrum", "definition": "An iterative delivery method with fixed-length sprints, a product backlog and defined accountabilities."},
    {"term": "Kanban", "definition": "A visual workflow that limits work in progress and manages flow and lead time rather than fixed iterations."},
]

GLOSSARIES["project-management"] = PROJECT_MANAGEMENT_GLOSSARY



